import type { DomainState } from '@/domain/entities';
import { orderFixture,issueFixture,productionAct,productionDate } from './production';
import { DEMO_IDS } from '@/data/seed';
import { executeFinishing,type FinishingCommand } from '@/services/transactions/finishing';
export const finishingDate='2026-10-16',finishingContext={actorId:DEMO_IDS.actor,at:'2026-10-16T00:00:00.000Z',role:'owner' as const};
export function finish(d:DomainState,c:FinishingCommand){const r=executeFinishing(d,c,finishingContext);if(!r.ok)throw new Error(c.kind+': '+r.error.message);return r.state;}
const cache=new Map<string,DomainState>();
export function finishingSource(pieces:2|3=3,full=false){const key='source'+pieces+full,saved=cache.get(key);if(saved)return structuredClone(saved);const f=orderFixture(pieces);let d=f.d;for(let index=0;index<pieces;index++){const quantity=full?200:[100,80,70][index],meters=index===0?quantity*2.7:quantity,issue=issueFixture({...f,d},'line-'+index,meters);d=productionAct(issue.d,{kind:'saveCutting',orderId:f.orderId,issueId:issue.issueId,date:productionDate,inputMeters:meters,usableMeters:meters,leftoverMeters:0,scrapMeters:0,remainingMeters:0,outputQuantity:quantity,unit:index===0?'PANEL':'SET',method:'دستی',operatorId:DEMO_IDS.actor,startOn:productionDate,finishOn:productionDate,reason:''});d=productionAct(d,{kind:'cuttingAction',id:Object.keys(d.production!.cuttings).at(-1)!,action:'POST'});d=productionAct(d,{kind:'createInspection',orderId:f.orderId,componentLotId:Object.keys(d.production!.componentLots).at(-1)!,date:productionDate,stage:'CUTTING',fromState:'QC_PENDING',inspectorId:DEMO_IDS.actor,quantity,accepted:quantity,held:0,rejected:0,rework:0,defect:'',remarks:''});d=productionAct(d,{kind:'inspectionAction',id:Object.keys(d.production!.inspections).at(-1)!,action:'POST'});}if(full){d=productionAct(d,{kind:'orderAction',id:f.orderId,action:'READY',reason:''});d=productionAct(d,{kind:'orderAction',id:f.orderId,action:'CLOSE',reason:''});}cache.set(key,structuredClone(d));return d;}
export const firstPlan=(d:DomainState)=>Object.values(d.finishing!.plans)[0];
export function assemblyFixture(pieces:2|3=3){const saved=cache.get('plan'+pieces);if(saved)return structuredClone(saved);let d=finishingSource(pieces);const order=Object.values(d.production!.orders)[0];d=finish(d,{kind:'savePlan',orderId:order.id,date:finishingDate,targetSets:70,startOn:finishingDate,finishOn:'2026-10-25',team:'میچنگ ٹیم',remarks:'',requirements:order.lines.map(line=>({key:line.key,perSet:1,unit:Object.values(d.production!.componentLots).find(l=>l.bomLineKey===line.key)!.unit,embroideryRequired:false}))});const id=firstPlan(d).id;for(const action of ['SUBMIT','APPROVE']as const)d=finish(d,{kind:'planAction',id,action});cache.set('plan'+pieces,structuredClone(d));return d;}
export function reserveAndIssue(d:DomainState,quantity=50){const p=firstPlan(d);for(const lot of Object.values(d.production!.componentLots).filter(l=>l.orderId===p.orderId)){d=finish(d,{kind:'reserveComponents',planId:p.id,componentLotId:lot.id,quantity,date:finishingDate});const reservationId=Object.keys(d.finishing!.reservations).at(-1)!;d=finish(d,{kind:'createIssue',planId:p.id,reservationId,quantity,date:finishingDate});const id=Object.keys(d.finishing!.issues).at(-1)!;for(const action of ['APPROVE','POST']as const)d=finish(d,{kind:'issueAction',id,action});}return d;}
export function matchingFixture(pieces:2|3=3){const saved=cache.get('matching'+pieces);if(saved)return structuredClone(saved);let d=reserveAndIssue(assemblyFixture(pieces));d=finish(d,{kind:'createMatching',planId:firstPlan(d).id,quantity:50,date:finishingDate});const id=Object.keys(d.finishing!.batches)[0];for(const action of ['APPROVE','POST']as const)d=finish(d,{kind:'matchingAction',id,action});cache.set('matching'+pieces,structuredClone(d));return d;}
export function qcFixture(){const saved=cache.get('qc');if(saved)return structuredClone(saved);let d=matchingFixture();const batchId=Object.keys(d.finishing!.batches)[0];d=finish(d,{kind:'createQC',batchId,date:finishingDate,fromState:'QC_PENDING',quantity:50,accepted:45,held:3,rejected:1,rework:1,inspectorId:DEMO_IDS.actor,defect:'داغ',remarks:''});const id=Object.keys(d.finishing!.inspections)[0];for(const action of ['APPROVE','POST']as const)d=finish(d,{kind:'qcAction',id,action});cache.set('qc',structuredClone(d));return d;}
export function packagingFixture(){const saved=cache.get('packaging');if(saved)return structuredClone(saved);let d=qcFixture();const batchId=Object.keys(d.finishing!.batches)[0],requirements=[];for(const [name,price]of [['پولی بیگ',500],['پروڈکٹ کارڈ',200],['برانڈ لیبل',100]]as const){d=finish(d,{kind:'saveMaterial',name,unit:'PIECE',category:'PACKAGING',reorderLevel:10,defaultCostPaisa:price,status:'ACTIVE'});const materialId=Object.keys(d.finishing!.materials).at(-1)!;requirements.push({materialId,perSet:1});d=finish(d,{kind:'createMaterialReceipt',materialId,date:finishingDate,quantity:100,unitCostPaisa:price,receiptKind:'OPENING',reference:name});const id=Object.keys(d.finishing!.materialReceipts).at(-1)!;for(const action of ['APPROVE','POST']as const)d=finish(d,{kind:'materialReceiptAction',id,action});}d=finish(d,{kind:'saveSKU',planId:firstPlan(d).id,code:'NT-P9-PLAIN-3P',name:'نور تین پیس',care:'ہاتھ سے دھوئیں',reorderLevel:5,targetPricePaisa:250000});const skuId=Object.keys(d.finishing!.skus)[0];d=finish(d,{kind:'savePackaging',batchId,skuId,date:finishingDate,quantity:30,method:'پولی بیگ',team:'پیکنگ ٹیم',startOn:finishingDate,finishOn:finishingDate,requirements,materialsAcknowledged:true,laborPerSetPaisa:1000,overheadPerSetPaisa:200});const id=Object.keys(d.finishing!.packaging)[0];d=finish(d,{kind:'packagingAction',id,action:'APPROVE'});for(const r of requirements)d=finish(d,{kind:'allocateMaterials',packagingId:id,materialId:r.materialId,date:finishingDate,quantity:30});d=finish(d,{kind:'saveLocation',name:'تیار مال وصولی',warehouseId:Object.keys(d.warehouses)[0],code:'FG-STAGE',zone:'تیار',rack:'',shelf:'',bin:'وصولی',area:'STAGING',status:'ACTIVE'});cache.set('packaging',structuredClone(d));return d;}
export function packedFixture(){const saved=cache.get('packed');if(saved)return structuredClone(saved);let d=packagingFixture();d=finish(d,{kind:'createCompletion',packagingId:Object.keys(d.finishing!.packaging)[0],quantity:30,date:finishingDate,locationId:Object.keys(d.finishing!.locations)[0]});const id=Object.keys(d.finishing!.completions)[0];for(const action of ['APPROVE','POST']as const)d=finish(d,{kind:'completionAction',id,action});cache.set('packed',structuredClone(d));return d;}
